CREATE TABLE if not exists `common_config`
(
    `id`          bigint   NOT NULL AUTO_INCREMENT COMMENT 'id',
    `tag`         varchar(200)      DEFAULT NULL COMMENT '配置标签',
    `config`      longtext COMMENT '配置',
    `remark`      varchar(100)      DEFAULT NULL COMMENT '说明',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_common_config_tag` (`tag`),
    KEY `index_tag` (`tag`) USING BTREE
) COMMENT ='配置表';

